with parsed as (select id, customer_id, ship_to, ship_to.country as ship_country, coalesce(attributes['device'], 'direct') as device_or_default, array_max(transform(items, i -> i.price)) as max_item_price, ship_to.city as ship_city, exists(items, i -> i.price > 100) as has_premium_item from carts where customer_id is null) select case when max_item_price >= 217 then 'LARGE' else 'SMALL' end as max_item_price_tier, count_if(ship_country = 'US') as us_events, round(avg(max_item_price), 2) as avg_max_item_price, sort_array(collect_set(ship_city)) as ship_city_list from parsed group by max_item_price_tier having round(avg(max_item_price), 2) < 1000000;
